(function(){
  const APP_GZ="";
  const CSS_GZ="";
  function decode64(s){const b=atob(s),a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);return a;}
  async function inflate(s){const stream=new Blob([decode64(s)]).stream().pipeThrough(new DecompressionStream("gzip"));return await new Response(stream).text();}
  (async()=>{
    if(!("DecompressionStream" in window)){throw new Error("This browser does not support compressed POS assets. Please update Chrome, Safari or Edge.");}
    const style=document.createElement("style");style.textContent=await inflate(CSS_GZ);document.head.appendChild(style);
    const code=await inflate(APP_GZ);const script=document.createElement("script");script.textContent=code;document.body.appendChild(script);
  })().catch(e=>{console.error(e);const m=document.getElementById("m");if(m)m.innerHTML='<div style="padding:24px;color:#9b1c1c">POS could not load: '+String(e.message||e)+'</div>';});
})();